function EmailPerformance(){const [data,setData]=useState<BrevoReport|null>(null);useEffect(()=>{fetch(`${import.meta.env.BASE_URL}api/brevo-reporting`).then(r=>r.json()).then(setData).catch(()=>setData({live:false,errors:["Brevo reporting request unavailable"]}))},[]);const m=data?.metrics;return <div className="page-stack"><div className={`source-banner ${data?.live?"live":""}`}><Send size={15}/><b>{!data?"Connecting to Brevo":data.live?"Brevo performance feed validated":"Brevo needs attention"}</b><span>{data?.diagnostic?.explanation||data?.errors?.[0]||"Testing reporting access…"}</span></div><div className="metric-grid">{[["Historical sent",m?.sent?.toLocaleString()??"Loading","Validated campaignStats"],["Historical delivered",m?.delivered?.toLocaleString()??"Loading","Validated campaignStats"],["Unique opens",m?.uniqueViews?.toLocaleString()??"Loading","Historical campaigns"],["Unique clicks",m?.uniqueClicks?.toLocaleString()??"Loading","Historical campaigns"]].map(x=><Metric key={x[0]} label={x[0]} value={x[1]} detail={x[2]}/>)}</div><div className="split-grid"><FieldPanel title="Reliably available" fields={["Sent","Delivered","Opens (viewed)","Unique opens","Clicks (clickers)","Unique clicks","Hard and soft bounces","Unsubscribes"]}/><FieldPanel title="Current limitations" fields={["No campaigns sent in the locked 28-day window","Website visits require GA4 attribution","Calls require WhatConverts attribution","Referral and admission fields are unavailable"]}/></div></div>}
